//! Vendored test fonts for `clazel-font` (phase-5.md items 5.1 and 5.9).
//!
//! Fonts are binary, so there is nothing to translate: the converter checks
//! that each file is the one its `SOURCE.md` names and that it still looks
//! like a font, and writes a table that embeds it with `include_bytes!`.
//!
//! - Each vendored file needs a line in `SOURCE.md` naming it in backquotes
//!   with its SHA-256 (`` - `X.ttf`: sha256 `…` ``); a changed or swapped
//!   file fails the conversion.
//! - Its first four bytes must be an `sfntVersion` of the OpenType font file
//!   chapter (`0x00010000`, `OTTO`, or Apple's `true`) or the collection tag
//!   `ttcf`; anything else fails.
//!
//! No font table is parsed here: that is the crate's job, and the
//! differential test's.

use std::fmt::Write as _;
use std::path::Path;

use sha2::{Digest, Sha256};

use super::hash::to_hex;

/// `tests/data/fonts-dejavu/`: DejaVu Serif 2.37.
pub const FILES_DEJAVU: &[&str] = &["DejaVuSerif.ttf"];
/// `tests/data/fonts-source-serif/`: Source Serif 4, `GPOS` extension lookups.
pub const FILES_SOURCE_SERIF: &[&str] = &["SourceSerif4-Regular.ttf"];
/// `tests/data/fonts-source-code-pro/`: a CFF font, reported unsupported.
pub const FILES_SOURCE_CODE_PRO: &[&str] = &["SourceCodePro-Regular.otf"];
/// `tests/data/fonts-fontations/`: small fonts from fontations' test data.
pub const FILES_FONTATIONS: &[&str] = &[
    "TTC.ttc",
    "glyf_components.ttf",
    "cmap12_font1.ttf",
    "cmap6.ttf",
];

/// The tags a font file may start with.
const MAGICS: [[u8; 4]; 4] = [[0, 1, 0, 0], *b"OTTO", *b"true", *b"ttcf"];

/// The files of the suite in `dir`, by its name.
fn files_of(name: &str) -> Result<&'static [&'static str], String> {
    match name {
        "fonts-dejavu" => Ok(FILES_DEJAVU),
        "fonts-source-serif" => Ok(FILES_SOURCE_SERIF),
        "fonts-source-code-pro" => Ok(FILES_SOURCE_CODE_PRO),
        "fonts-fontations" => Ok(FILES_FONTATIONS),
        _ => Err(format!("no font list for suite {name:?}")),
    }
}

/// The SHA-256 that `SOURCE.md` gives for `file`, from the line that names
/// it in backquotes.
fn listed_hash(source: &str, file: &str) -> Result<String, String> {
    let quoted = format!("`{file}`");
    let line = source
        .lines()
        .find(|l| l.trim_start().starts_with(&format!("- {quoted}")))
        .ok_or_else(|| format!("SOURCE.md has no \"- {quoted}: sha256 `…`\" line"))?;
    let after = line
        .split_once("sha256 `")
        .map(|(_, rest)| rest)
        .ok_or_else(|| format!("SOURCE.md's line for {quoted} has no sha256"))?;
    let hex: String = after.chars().take_while(char::is_ascii_hexdigit).collect();
    if hex.len() != 64 || !after.get(64..).is_some_and(|r| r.starts_with('`')) {
        return Err(format!(
            "SOURCE.md's sha256 for {quoted} is not 64 hex digits"
        ));
    }
    Ok(hex.to_ascii_lowercase())
}

/// Check the suite in `dir` and write its table.
pub fn convert(dir: &Path) -> Result<String, String> {
    let name = dir
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| format!("{}: no directory name", dir.display()))?;
    let files = files_of(name)?;
    let source = std::fs::read_to_string(dir.join("SOURCE.md"))
        .map_err(|e| format!("SOURCE.md: {e}"))?;
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo xtask testdata` from `tests/data/{name}/` \
         (xtask/src/testdata/fonts.rs). Do not edit.\n\
         \n\
         /// One vendored font file, checked against `SOURCE.md` when generated.\n\
         pub struct Case {{\n    \
             /// The file's name in `tests/data/{name}/`.\n    \
             pub file: &'static str,\n    \
             /// Its SHA-256, as `SOURCE.md` lists it.\n    \
             pub sha256: &'static str,\n    \
             /// Its bytes.\n    \
             pub bytes: &'static [u8],\n\
         }}\n\
         \n\
         /// Every font of the suite.\n\
         pub const FONTS: &[Case] = &["
    );
    for file in files {
        let bytes = std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))?;
        let hash = to_hex(&Sha256::digest(&bytes));
        let listed = listed_hash(&source, file)?;
        if hash != listed {
            return Err(format!(
                "{file}: SHA-256 {hash} differs from SOURCE.md's {listed}"
            ));
        }
        let magic: Option<[u8; 4]> = bytes.get(..4).and_then(|m| m.try_into().ok());
        if !magic.is_some_and(|m| MAGICS.contains(&m)) {
            return Err(format!(
                "{file}: does not start with an sfntVersion or `ttcf`"
            ));
        }
        let _ = writeln!(
            out,
            "    Case {{\n        \
                 file: {file:?},\n        \
                 sha256: {hash:?},\n        \
                 bytes: include_bytes!(\"../data/{name}/{file}\"),\n    \
             }},"
        );
    }
    out.push_str("];\n");
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::listed_hash;

    #[test]
    fn hash_lines() {
        let h = "ab".repeat(32);
        let src = format!("x\n- `A.ttf`: sha256 `{h}` (notes)\n");
        assert_eq!(listed_hash(&src, "A.ttf"), Ok(h));
        assert!(listed_hash(&src, "B.ttf").is_err());
        assert!(listed_hash("- `A.ttf`: sha256 `abc`\n", "A.ttf").is_err());
    }
}
